import json
from fractions import Fraction as F

def expr(a):
    a = F(a)
    d1 = a*a + 6*a + 9          # denominator of first fraction
    d2 = a*a + 3*a              # denominator of divisor fraction
    n2 = a - 3                  # numerator of divisor fraction (must be nonzero)
    d3 = a - 1
    if d1 == 0 or d2 == 0 or n2 == 0 or d3 == 0:
        return None
    first = (a*a - 9) / d1
    divisor = n2 / d2
    return first / divisor - (a - a*a) / d3

# check simplification: expression == 2a on many valid rationals
samples = [F(n, d) for n in range(-20, 21) for d in (1, 2, 3, 5)]
checked = 0
ok = True
for s in samples:
    v = expr(s)
    if v is None:
        continue
    checked += 1
    if v != 2 * s:
        ok = False

valid = {}
for a in [0, 1, 2, 3]:
    v = expr(a)
    if v is not None:
        valid[a] = v

if ok and checked > 0 and len(valid) == 1:
    a, v = next(iter(valid.items()))
    final = f"Simplified: 2a; choose a={a} (0, 1, 3 make the expression undefined); value = {v}"
    print(json.dumps({
        "final_answer": final,
        "evidence": {
            "simplification_verified_on_samples": checked,
            "valid_values": {str(k): str(val) for k, val in valid.items()},
        },
    }))
else:
    print("UNSUPPORTED")
